package com.bank.compliance;

import java.util.*;
import java.util.logging.*;

public class ComplianceDemo {
    private static final Logger log = Logger.getLogger("Compliance");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(1L, "Rajesh"),
            new Employee(2L, "Priya"),
            new Employee(3L, "Amit")
        );
        ComplianceService service = new ComplianceService();
        List<String> approved = service.approvedNamesImmutable(staff);
        log.info(() -> "Approved (read-only): " + approved);
        try {
            approved.add("Intruder"); // attempt to tamper
        } catch (UnsupportedOperationException ex) {
            log.warning("Tamper attempt rejected: list is unmodifiable");
        }
    }
}

