class Employee {
    private final Long id;
    private final String name;
        Employee(Long id, String name) { this.id = id;
        this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/ComplianceService.java ───
class ComplianceService {
    // Java 10+: collect straight into an immutable list.
    List<String> approvedNamesImmutable(List<Employee> employees) {
        return employees.stream()
            .map(Employee::getName)
            .collect(java.util.stream.Collectors.toUnmodifiableList());
    }

    // Java 8/9 portable alternative (kept for reference):
    List<String> approvedNamesPortable(List<Employee> employees) {
        return employees.stream()
            .map(Employee::getName)
            .collect(java.util.stream.Collectors.collectingAndThen(
                java.util.stream.Collectors.toList(),
                Collections::unmodifiableList));
    }
}
